        "checklist_item": {
          "check_id": "CHK-W6B15-2-002",
          "property_id": "PROP-W6B15-2",
          "title": "Does signature malleability in EIP-7702 Authorization allow recovery to an unintended address?",
          "severity": "Critical",
          "mindset": "Boundary Guard",
          "is_boundary_check": true,
          "reachability": {
            "classification": "external-reachable",
            "entry_points": [
              "Transaction",
              "P2P"
            ],
            "attacker_controlled": true,
            "validation_layers": [
              "Transaction validation",
              "Signature verification"
            ],
            "bug_bounty_scope": "in-scope",
            "notes": "Attacker controls the (y_parity, r, s) values in the Authorization tuple. A malleable signature could recover to a different address."
          },
          "test_procedure": "1. Generate a valid EIP-7702 Authorization with a known signing address.\n2. Compute the malleable counterpart signature: s' = secp256k1n - s.\n3. Submit both the original and malleable signatures to the signature recovery function.\n4. Verify that if s' > secp256k1n/2, it is rejected before recovery.\n5. If not rejected, compare the recovered addresses to detect the vulnerability.\n6. Document any code paths where malleable signatures bypass validation.\n7. Test via both Transaction submission and P2P propagation entry points.",
          "bug_class": "Cryptographic Validation",
          "risk_category": "Spoofing",
          "notes": "Source: PROP-W6B15-2, Trust Boundary: tb-006, Actors: actor-eip7702-authorizer, actor-el-node"
        },
        "code_scope": {
